import chroma from 'chroma-js'
import React, { memo, useCallback, useEffect, useMemo, useState } from 'react'
import { GeoJSON, MapContainer, TileLayer } from 'react-leaflet'
import { METRO_AREAS } from './data/countyElectionData.js'
import InsetMap from './InsetMap.jsx'
import styles from './SimulatorMap.module.css'

const MO_CENTER = [38.4, -92.5]
const MO_ZOOM = 6.5

// Blue (D) -> White (even) -> Red (R)
const colorScale = chroma.scale(['#0015BC', '#f0f0f0', '#E81B23']).domain([-40, 0, 40])

const metroAreaList = Object.values(METRO_AREAS)

function SimulatorMap({ countyResults }) {
  const [geojsonData, setGeojsonData] = useState(null)

  useEffect(() => {
    fetch('/mo_counties.geojson')
        .then((response) => response.json())
        .then((data) => setGeojsonData(data))
        .catch((error) => console.error('Error fetching county GeoJSON:', error))
  }, [])

  const countyLookup = useMemo(() => {
    if (!countyResults) return {}
    const lookup = {}
    for (const c of countyResults) {
      lookup[c.countyfips] = c
    }
    return lookup
  }, [countyResults])

  const styleFeature = useCallback((feature) => {
    const fips = feature.properties.countyfips
    const result = countyLookup[fips]
    const margin = result ? parseFloat(result.margin) : 0
    return {
      fillColor: colorScale(margin).hex(),
      weight: 1,
      opacity: 1,
      color: 'white',
      dashArray: '1',
      fillOpacity: 0.8,
    }
  }, [countyLookup])

  const onEachFeature = useCallback((feature, layer) => {
    const fips = feature.properties.countyfips
    const result = countyLookup[fips]

    if (result) {
      const margin = parseFloat(result.margin)
      const prefix = margin > 0 ? 'R+' : 'D+'
      layer.bindTooltip(
          `<b>${result.countyname}</b><br/>` +
          `R: ${result.repPct}% | D: ${result.demPct}%<br/>` +
          `Margin: ${prefix}${Math.abs(margin).toFixed(1)}`,
          { sticky: true },
      )

      layer.bindPopup(
          `<div style="min-width:180px">` +
          `<h4 style="margin:0 0 6px">${result.countyname} County</h4>` +
          `<table style="width:100%;font-size:12px">` +
          `<tr><td>Republican:</td><td style="text-align:right;color:#E81B23"><b>${result.repVotes.toLocaleString()}</b> (${result.repPct}%)</td></tr>` +
          `<tr><td>Democrat:</td><td style="text-align:right;color:#0015BC"><b>${result.demVotes.toLocaleString()}</b> (${result.demPct}%)</td></tr>` +
          `<tr><td>Total:</td><td style="text-align:right"><b>${result.totalVotes.toLocaleString()}</b></td></tr>` +
          `<tr><td>Margin:</td><td style="text-align:right"><b>${prefix}${Math.abs(margin).toFixed(1)}%</b></td></tr>` +
          `<tr><td>Type:</td><td style="text-align:right">${result.classification}</td></tr>` +
          `</table></div>`,
      )
    } else {
      layer.bindTooltip(feature.properties.countyname || 'Unknown')
    }

    layer.on({
      mouseover: (e) => {
        e.target.setStyle({ weight: 2, color: '#333', fillOpacity: 0.9 })
        e.target.bringToFront()
      },
      mouseout: (e) => {
        e.target.setStyle({ weight: 1, color: 'white', fillOpacity: 0.8 })
      },
    })
  }, [countyLookup])

  // Create a key that changes when results change to force GeoJSON re-render
  const mapKey = useMemo(() => {
    if (!countyResults) return 'no-results'
    return countyResults.map((c) => c.margin).join(',')
  }, [countyResults])

  if (!countyResults) {
    return <div className={styles.noData}>Run a simulation with a statewide race to see the county map</div>
  }

  return (
    <div className={styles.mapWrapper}>
      <div className={styles.mainMap}>
        <MapContainer
          center={MO_CENTER}
          zoom={MO_ZOOM}
          zoomControl={true}
          style={{ height: '100%', width: '100%' }}
        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}{r}.png"
            attribution='&copy; <a href="https://carto.com/">CARTO</a>'
          />
          {geojsonData && (
            <GeoJSON
              key={mapKey}
              data={geojsonData}
              style={styleFeature}
              onEachFeature={onEachFeature}
            />
          )}
        </MapContainer>
        <div className={styles.legend}>
          <div className={styles.legendTitle}>Partisan Margin</div>
          <div className={styles.legendGradient}>
            <span style={{ color: '#0015BC', fontWeight: 600 }}>D</span>
            <div
              className={styles.gradientBar}
              style={{
                background: `linear-gradient(to right, #0015BC, #f0f0f0, #E81B23)`,
              }}
            />
            <span style={{ color: '#E81B23', fontWeight: 600 }}>R</span>
          </div>
          <div className={styles.legendLabels}>
            <span>+40</span>
            <span>Even</span>
            <span>+40</span>
          </div>
        </div>
      </div>

      <div className={styles.insetRow}>
        {metroAreaList.map((metro) => (
          <InsetMap
            key={metro.name}
            geojsonData={geojsonData}
            countyLookup={countyLookup}
            metroArea={metro}
            colorScale={colorScale}
          />
        ))}
      </div>
    </div>
  )
}

export default memo(SimulatorMap)
