import { InboxOutlined } from '@ant-design/icons'
import { Input, Modal, Select, Table, Typography } from 'antd'
import React, { memo, useCallback, useMemo, useState } from 'react'
import { readExcelFile } from '../utils/ExcelProcessingUtils.jsx'
import { getCountyClassification } from './data/countyElectionData.js'
import { RACE_LABELS, RACE_TYPES } from './data/missouriElectionData.js'
import styles from './CountyDataImportModal.module.css'

const { Text } = Typography

// Only statewide races make sense for county data
const statewidRaceOptions = [
  RACE_TYPES.PRESIDENTIAL_2020,
  RACE_TYPES.SENATE_2022,
  RACE_TYPES.GOVERNOR_2020,
].map((key) => ({ value: key, label: RACE_LABELS[key] }))

// Known MO county FIPS (115 entities)
const VALID_FIPS_COUNT = 115

function CountyDataImportModal({ open, onClose, onSave }) {
  const [fileData, setFileData] = useState(null)
  const [fileName, setFileName] = useState('')
  const [raceKey, setRaceKey] = useState(RACE_TYPES.PRESIDENTIAL_2020)
  const [customRaceLabel, setCustomRaceLabel] = useState('')
  const [columnMapping, setColumnMapping] = useState({
    fips: null, name: null, repVotes: null, demVotes: null, totalVotes: null,
  })
  const [dragActive, setDragActive] = useState(false)
  const [validationResult, setValidationResult] = useState(null)
  const [saving, setSaving] = useState(false)

  const handleFile = useCallback(async (file) => {
    try {
      const data = await readExcelFile(file)
      setFileData(data)
      setFileName(file.name)
      setValidationResult(null)

      // Auto-detect columns by name patterns
      const mapping = { fips: null, name: null, repVotes: null, demVotes: null, totalVotes: null }
      for (const col of data.columns) {
        const lower = col.toLowerCase()
        if (lower.includes('fips') || lower.includes('code')) mapping.fips = col
        else if (lower.includes('county') || lower.includes('name')) mapping.name = col
        else if (lower.includes('rep') || lower.includes('trump') || lower.includes('republican')) mapping.repVotes = col
        else if (lower.includes('dem') || lower.includes('biden') || lower.includes('democrat')) mapping.demVotes = col
        else if (lower.includes('total') || lower.includes('all')) mapping.totalVotes = col
      }
      setColumnMapping(mapping)
    } catch (err) {
      setValidationResult({ success: false, message: `Error reading file: ${err.message}` })
    }
  }, [])

  const handleDrop = useCallback((e) => {
    e.preventDefault()
    setDragActive(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const handleFileInput = useCallback((e) => {
    const file = e.target.files[0]
    if (file) handleFile(file)
  }, [handleFile])

  const columnOptions = useMemo(() => {
    if (!fileData) return []
    return fileData.columns.map((c) => ({ value: c, label: c }))
  }, [fileData])

  const parsedCounties = useMemo(() => {
    if (!fileData || !columnMapping.fips || !columnMapping.repVotes || !columnMapping.demVotes) return null

    const getColLetter = (colName) => {
      const match = colName.match(/\(([^)]+)\)/)
      return match ? match[1] : null
    }

    const fipsCol = getColLetter(columnMapping.fips)
    const nameCol = columnMapping.name ? getColLetter(columnMapping.name) : null
    const repCol = getColLetter(columnMapping.repVotes)
    const demCol = getColLetter(columnMapping.demVotes)
    const totalCol = columnMapping.totalVotes ? getColLetter(columnMapping.totalVotes) : null

    if (!fipsCol || !repCol || !demCol) return null

    const rows = fileData.data[fipsCol]?.length || 0
    const counties = []

    for (let i = 0; i < rows; i++) {
      let fips = String(fileData.data[fipsCol][i] || '').trim()
      // Normalize FIPS: strip state prefix if 5 digits, pad to 3 digits
      if (fips.length === 5 && fips.startsWith('29')) fips = fips.slice(2)
      if (fips.length < 3) fips = fips.padStart(3, '0')

      const repVotes = parseInt(fileData.data[repCol][i], 10) || 0
      const demVotes = parseInt(fileData.data[demCol][i], 10) || 0
      const totalVotes = totalCol ? (parseInt(fileData.data[totalCol][i], 10) || 0) : repVotes + demVotes
      const countyname = nameCol ? String(fileData.data[nameCol][i] || '') : fips

      if (!fips || fips === '000') continue

      const repPct = totalVotes > 0 ? parseFloat((repVotes / totalVotes * 100).toFixed(1)) : 0
      const demPct = totalVotes > 0 ? parseFloat((demVotes / totalVotes * 100).toFixed(1)) : 0

      counties.push({
        countyfips: fips,
        countyname,
        classification: getCountyClassification(fips),
        repVotes,
        demVotes,
        otherVotes: Math.max(0, totalVotes - repVotes - demVotes),
        totalVotes,
        repPct,
        demPct,
      })
    }

    return counties
  }, [fileData, columnMapping])

  const validate = useCallback(() => {
    if (!parsedCounties) {
      setValidationResult({ success: false, message: 'Map required columns (FIPS, Rep Votes, Dem Votes) first.' })
      return false
    }
    if (parsedCounties.length < 100) {
      setValidationResult({ success: false, message: `Only ${parsedCounties.length} valid rows found. Expected ~${VALID_FIPS_COUNT} counties.` })
      return false
    }
    const fipsCounts = new Map()
    for (const c of parsedCounties) {
      fipsCounts.set(c.countyfips, (fipsCounts.get(c.countyfips) || 0) + 1)
    }
    const duplicates = [...fipsCounts.entries()].filter(([, count]) => count > 1)
    if (duplicates.length > 0) {
      setValidationResult({ success: false, message: `Duplicate FIPS codes found: ${duplicates.map(([f]) => f).join(', ')}` })
      return false
    }
    setValidationResult({ success: true, message: `${parsedCounties.length} counties validated successfully.` })
    return true
  }, [parsedCounties])

  const handleSave = useCallback(async () => {
    if (!validate()) return
    setSaving(true)
    const label = customRaceLabel || RACE_LABELS[raceKey] || raceKey
    const result = await onSave(raceKey, label, parsedCounties)
    setSaving(false)
    if (result?.success) {
      onClose()
      setFileData(null)
      setFileName('')
      setValidationResult(null)
    } else {
      setValidationResult({ success: false, message: result?.error || 'Failed to save data.' })
    }
  }, [validate, raceKey, customRaceLabel, parsedCounties, onSave, onClose])

  const previewData = useMemo(() => {
    if (!parsedCounties) return []
    return parsedCounties.slice(0, 10).map((c, i) => ({ key: i, ...c }))
  }, [parsedCounties])

  return (
    <Modal
      title="Import County Election Data"
      open={open}
      onCancel={onClose}
      onOk={handleSave}
      okText="Import & Save"
      okButtonProps={{ disabled: !parsedCounties || saving, loading: saving }}
      width={700}
      destroyOnClose
    >
      {/* Drop Zone */}
      <div
        className={`${styles.dropZone} ${dragActive ? styles.dropZoneActive : ''}`}
        onDragOver={(e) => {
          e.preventDefault()
          setDragActive(true)
        }}
        onDragLeave={() => setDragActive(false)}
        onDrop={handleDrop}
        onClick={() => document.getElementById('county-import-file').click()}
      >
        <div className={styles.dropIcon}><InboxOutlined /></div>
        <div className={styles.dropText}>Click or drag a CSV/Excel file here</div>
        <div className={styles.dropHint}>File should contain county FIPS codes, Republican votes, and Democrat votes</div>
        {fileName && <div className={styles.fileName}>{fileName}</div>}
        <input
          id="county-import-file"
          type="file"
          accept=".csv,.xlsx,.xls"
          style={{ display: 'none' }}
          onChange={handleFileInput}
        />
      </div>

      {/* Race Selection */}
      <div className={styles.formSection}>
        <Text className={styles.formLabel}>Race / Election</Text>
        <Select
          value={raceKey}
          onChange={setRaceKey}
          options={[
            ...statewidRaceOptions,
            { value: 'custom', label: 'Custom Race...' },
          ]}
          style={{ width: '100%' }}
        />
        {raceKey === 'custom' && (
          <Input
            placeholder="Enter race label (e.g., 2024 Presidential)"
            value={customRaceLabel}
            onChange={(e) => setCustomRaceLabel(e.target.value)}
            style={{ marginTop: 8 }}
          />
        )}
      </div>

      {/* Column Mapping */}
      {fileData && (
        <div className={styles.formSection}>
          <Text className={styles.formLabel}>Column Mapping</Text>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
            <div>
              <Text type="secondary" style={{ fontSize: 12 }}>FIPS Code *</Text>
              <Select value={columnMapping.fips} onChange={(v) => setColumnMapping((p) => ({ ...p, fips: v }))} options={columnOptions} style={{ width: '100%' }} placeholder="Select..." allowClear />
            </div>
            <div>
              <Text type="secondary" style={{ fontSize: 12 }}>County Name</Text>
              <Select value={columnMapping.name} onChange={(v) => setColumnMapping((p) => ({ ...p, name: v }))} options={columnOptions} style={{ width: '100%' }} placeholder="Optional" allowClear />
            </div>
            <div>
              <Text type="secondary" style={{ fontSize: 12 }}>Republican Votes *</Text>
              <Select value={columnMapping.repVotes} onChange={(v) => setColumnMapping((p) => ({ ...p, repVotes: v }))} options={columnOptions} style={{ width: '100%' }} placeholder="Select..." allowClear />
            </div>
            <div>
              <Text type="secondary" style={{ fontSize: 12 }}>Democrat Votes *</Text>
              <Select value={columnMapping.demVotes} onChange={(v) => setColumnMapping((p) => ({ ...p, demVotes: v }))} options={columnOptions} style={{ width: '100%' }} placeholder="Select..." allowClear />
            </div>
            <div>
              <Text type="secondary" style={{ fontSize: 12 }}>Total Votes</Text>
              <Select value={columnMapping.totalVotes} onChange={(v) => setColumnMapping((p) => ({ ...p, totalVotes: v }))} options={columnOptions} style={{ width: '100%' }} placeholder="Optional (auto-calc)" allowClear />
            </div>
          </div>
        </div>
      )}

      {/* Preview */}
      {previewData.length > 0 && (
        <div className={styles.formSection}>
          <Text className={styles.formLabel}>Preview (first 10 rows)</Text>
          <div className={styles.previewTable}>
            <Table
              dataSource={previewData}
              columns={[
                { title: 'FIPS', dataIndex: 'countyfips', width: 60 },
                { title: 'County', dataIndex: 'countyname', width: 120 },
                { title: 'R Votes', dataIndex: 'repVotes', width: 80, render: (v) => v.toLocaleString() },
                { title: 'D Votes', dataIndex: 'demVotes', width: 80, render: (v) => v.toLocaleString() },
                { title: 'R%', dataIndex: 'repPct', width: 50 },
                { title: 'D%', dataIndex: 'demPct', width: 50 },
              ]}
              size="small"
              pagination={false}
            />
          </div>
        </div>
      )}

      {/* Validation */}
      {validationResult && (
        <div className={`${styles.validationMsg} ${validationResult.success ? styles.validationSuccess : styles.validationError}`}>
          {validationResult.message}
        </div>
      )}
    </Modal>
  )
}

export default memo(CountyDataImportModal)
