import { PlayCircleOutlined, ReloadOutlined, SaveOutlined, UploadOutlined } from '@ant-design/icons'
import { Button, Card, Divider, Select, Slider, Typography } from 'antd'
import React, { memo, useCallback, useMemo } from 'react'
import { RACE_LABELS } from './data/missouriElectionData.js'
import styles from './SimulatorToolPanel.module.css'

const { Text, Title } = Typography

const raceOptions = Object.entries(RACE_LABELS).map(([value, label]) => ({ value, label }))

function SimulatorToolPanel({
  selectedRace, setSelectedRace,
  turnoutPercent, setTurnoutPercent,
  partySwing, setPartySwing,
  urbanModifier, setUrbanModifier,
  suburbanModifier, setSuburbanModifier,
  ruralModifier, setRuralModifier,
  simulationResults,
  runSimulation, saveScenario, clearScenarios, resetParameters,
  setShowImportModal,
}) {
  const handleRunSimulation = useCallback(() => {
    runSimulation()
  }, [runSimulation])

  const turnoutMarks = useMemo(() => ({ 50: '50%', 75: '75%', 100: '100%' }), [])
  const swingMarks = useMemo(() => ({ '-10': '-10', '0': '0', '10': '+10' }), [])
  const modifierMarks = useMemo(() => ({ '-5': '-5', '0': '0', '5': '+5' }), [])

  return (
    <div className={styles.toolPanel}>
      <Title level={5} className={styles.panelTitle}>Simulation Parameters</Title>

      <Card size="small" className={styles.card}>
        <Text strong>Select Race</Text>
        <Select
          value={selectedRace}
          onChange={setSelectedRace}
          options={raceOptions}
          className={styles.fullWidth}
        />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Turnout Adjustment: {turnoutPercent}%</Text>
        <Slider min={50} max={100} value={turnoutPercent} onChange={setTurnoutPercent} marks={turnoutMarks} />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Party Swing (R+/D-): {partySwing > 0 ? '+' : ''}{partySwing}%</Text>
        <Slider min={-10} max={10} step={0.5} value={partySwing} onChange={setPartySwing} marks={swingMarks} />
      </Card>

      <Card size="small" className={styles.card}>
        <Text strong>Demographic Modifiers</Text>
        <Divider style={{ margin: '8px 0' }} />
        <Text>Urban: {urbanModifier > 0 ? '+' : ''}{urbanModifier}%</Text>
        <Slider min={-5} max={5} step={0.5} value={urbanModifier} onChange={setUrbanModifier} marks={modifierMarks} />
        <Text>Suburban: {suburbanModifier > 0 ? '+' : ''}{suburbanModifier}%</Text>
        <Slider min={-5} max={5} step={0.5} value={suburbanModifier} onChange={setSuburbanModifier} marks={modifierMarks} />
        <Text>Rural: {ruralModifier > 0 ? '+' : ''}{ruralModifier}%</Text>
        <Slider min={-5} max={5} step={0.5} value={ruralModifier} onChange={setRuralModifier} marks={modifierMarks} />
      </Card>

      <div className={styles.buttonGroup}>
        <Button type="primary" icon={<PlayCircleOutlined />} onClick={handleRunSimulation} block>
          Run Simulation
        </Button>
        <Button icon={<SaveOutlined />} onClick={saveScenario} disabled={!simulationResults} block>
          Save Scenario
        </Button>
        <Button icon={<ReloadOutlined />} onClick={resetParameters} block>
          Reset
        </Button>
        <Button onClick={clearScenarios} size="small" block>
          Clear Scenarios
        </Button>
        <Divider style={{ margin: '8px 0' }} />
        <Button icon={<UploadOutlined />} onClick={() => setShowImportModal(true)} block>
          Import County Data
        </Button>
      </div>
    </div>
  )
}

export default memo(SimulatorToolPanel)
