import L from 'leaflet'
import React, { memo, useMemo } from 'react'
import { GeoJSON, MapContainer } from 'react-leaflet'
import styles from './SimulatorMap.module.css'

function InsetMap({ geojsonData, countyLookup, metroArea, colorScale }) {
  const metroCountySet = useMemo(() => new Set(metroArea.counties), [metroArea.counties])

  const filteredGeojson = useMemo(() => {
    if (!geojsonData) return null
    return {
      ...geojsonData,
      features: geojsonData.features.filter((f) =>
        metroCountySet.has(f.properties.countyfips),
      ),
    }
  }, [geojsonData, metroCountySet])

  const bounds = useMemo(
      () => L.latLngBounds(metroArea.bounds[0], metroArea.bounds[1]),
      [metroArea.bounds],
  )

  const styleFeature = useMemo(() => (feature) => {
    const fips = feature.properties.countyfips
    const result = countyLookup[fips]
    const margin = result ? parseFloat(result.margin) : 0
    return {
      fillColor: colorScale(margin).hex(),
      weight: 1,
      opacity: 1,
      color: '#666',
      fillOpacity: 0.8,
    }
  }, [countyLookup, colorScale])

  const onEachFeature = useMemo(() => (feature, layer) => {
    const fips = feature.properties.countyfips
    const result = countyLookup[fips]
    if (result) {
      const margin = parseFloat(result.margin)
      const prefix = margin > 0 ? 'R+' : 'D+'
      layer.bindTooltip(
          `<b>${result.countyname}</b><br/>${prefix}${Math.abs(margin).toFixed(1)}`,
          { sticky: true, className: 'county-tooltip' },
      )
    }
  }, [countyLookup])

  if (!filteredGeojson || filteredGeojson.features.length === 0) return null

  const mapKey = Object.keys(countyLookup).length > 0 ?
    JSON.stringify(metroArea.counties.map((f) => countyLookup[f]?.margin || '0')) :
    'empty'

  return (
    <div className={styles.insetContainer}>
      <div className={styles.insetLabel}>{metroArea.name}</div>
      <div className={styles.insetMapBox}>
        <MapContainer
          bounds={bounds}
          zoomControl={false}
          attributionControl={false}
          dragging={false}
          scrollWheelZoom={false}
          doubleClickZoom={false}
          touchZoom={false}
          boxZoom={false}
          keyboard={false}
          style={{ height: '100%', width: '100%' }}
        >
          <GeoJSON
            key={mapKey}
            data={filteredGeojson}
            style={styleFeature}
            onEachFeature={onEachFeature}
          />
        </MapContainer>
      </div>
    </div>
  )
}

export default memo(InsetMap)
