import { useCallback, useEffect, useState } from 'react'
import { collection, doc, getDocs, setDoc } from 'firebase/firestore'
import { db } from '../../auth/firebase.jsx'
import { countyElectionData } from '../data/countyElectionData.js'
import { RACE_TYPES } from '../data/missouriElectionData.js'

const COLLECTION_NAME = 'electionData'

const useCountyElectionData = () => {
  const [countyData, setCountyData] = useState(countyElectionData)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [availableRaces, setAvailableRaces] = useState(Object.keys(countyElectionData))

  // Load county data from Firestore, fall back to local data
  useEffect(() => {
    let cancelled = false

    const loadFromFirestore = async () => {
      try {
        const snapshot = await getDocs(collection(db, COLLECTION_NAME))
        if (cancelled) return

        if (!snapshot.empty) {
          const firestoreData = {}
          snapshot.forEach((docSnap) => {
            const data = docSnap.data()
            if (data.raceKey && data.counties) {
              firestoreData[data.raceKey] = data
            }
          })

          if (Object.keys(firestoreData).length > 0) {
            // Merge Firestore data with local fallback (Firestore takes priority)
            setCountyData((prev) => ({ ...prev, ...firestoreData }))
            setAvailableRaces((prev) => {
              const all = new Set([...prev, ...Object.keys(firestoreData)])
              return Array.from(all)
            })
          }
        }
      } catch (err) {
        console.warn('Could not load election data from Firestore, using local fallback:', err.message)
        setError(err.message)
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    loadFromFirestore()
    return () => {
      cancelled = true
    }
  }, [])

  // Save a race dataset to Firestore
  const saveRaceData = useCallback(async (raceKey, raceLabel, countiesArray) => {
    try {
      const statewide = countiesArray.reduce(
          (acc, c) => ({
            repVotes: acc.repVotes + c.repVotes,
            demVotes: acc.demVotes + c.demVotes,
            otherVotes: acc.otherVotes + (c.otherVotes || 0),
            totalVotes: acc.totalVotes + c.totalVotes,
          }),
          { repVotes: 0, demVotes: 0, otherVotes: 0, totalVotes: 0 },
      )
      statewide.repPct = parseFloat((statewide.repVotes / statewide.totalVotes * 100).toFixed(1))
      statewide.demPct = parseFloat((statewide.demVotes / statewide.totalVotes * 100).toFixed(1))

      const docData = {
        raceKey,
        raceLabel,
        importedAt: new Date().toISOString(),
        statewide,
        counties: countiesArray,
      }

      await setDoc(doc(db, COLLECTION_NAME, raceKey), docData)

      // Update local state
      setCountyData((prev) => ({ ...prev, [raceKey]: docData }))
      setAvailableRaces((prev) => {
        const all = new Set([...prev, raceKey])
        return Array.from(all)
      })

      return { success: true }
    } catch (err) {
      console.error('Error saving election data to Firestore:', err)
      return { success: false, error: err.message }
    }
  }, [])

  // Get county data for a specific race
  const getCountyDataForRace = useCallback((raceKey) => {
    // Only return county data for statewide races, not congressional districts
    const statewidRaces = [RACE_TYPES.PRESIDENTIAL_2020, RACE_TYPES.SENATE_2022, RACE_TYPES.GOVERNOR_2020]
    if (statewidRaces.includes(raceKey) || (countyData[raceKey] && countyData[raceKey].counties)) {
      return countyData[raceKey] || null
    }
    return null
  }, [countyData])

  return {
    countyData,
    loading,
    error,
    availableRaces,
    saveRaceData,
    getCountyDataForRace,
  }
}

export default useCountyElectionData
