import { Card, Col, Empty, Row, Statistic, Table, Tabs, Tag, Typography } from 'antd'
import React, { memo, useMemo } from 'react'
import { RACE_LABELS } from './data/missouriElectionData.js'
import SimulatorMap from './SimulatorMap.jsx'
import styles from './SimulatorResults.module.css'

const { Title } = Typography

const districtColumns = [
  { title: 'District', dataIndex: 'name', key: 'name', width: 200, fixed: 'left' },
  { title: 'Type', dataIndex: 'classification', key: 'classification', width: 100,
    render: (val) => (
      <Tag color={val === 'urban' ? 'blue' : val === 'suburban' ? 'green' : 'orange'}>
        {val}
      </Tag>
    ),
  },
  { title: 'R Votes', dataIndex: 'repVotes', key: 'repVotes', width: 100, render: (v) => v?.toLocaleString() },
  { title: 'D Votes', dataIndex: 'demVotes', key: 'demVotes', width: 100, render: (v) => v?.toLocaleString() },
  { title: 'R %', dataIndex: 'repPct', key: 'repPct', width: 80 },
  { title: 'D %', dataIndex: 'demPct', key: 'demPct', width: 80 },
  { title: 'Margin', dataIndex: 'margin', key: 'margin', width: 100,
    render: (val) => {
      const num = parseFloat(val)
      return <Tag color={num > 0 ? 'red' : 'blue'}>{num > 0 ? 'R+' : 'D+'}{Math.abs(num).toFixed(1)}</Tag>
    },
    sorter: (a, b) => parseFloat(a.margin) - parseFloat(b.margin),
  },
  { title: 'Swing', dataIndex: 'swingFromBaseline', key: 'swingFromBaseline', width: 100,
    render: (val) => {
      const num = parseFloat(val)
      if (num === 0) return <span>-</span>
      return <Tag color={num > 0 ? 'red' : 'blue'}>{num > 0 ? '+' : ''}{num}</Tag>
    },
  },
]

function SimulatorResults({ simulationResults, scenarios, selectedRace, countyResults }) {
  const tabItems = useMemo(() => {
    const items = [
      {
        key: 'results',
        label: 'Results',
        children: simulationResults ? (
          <div className={styles.resultsContent}>
            <Row gutter={[16, 16]} className={styles.summaryRow}>
              <Col xs={24} sm={12} md={6}>
                <Card size="small">
                  <Statistic
                    title="Projected Winner"
                    value={simulationResults.statewide.winner}
                    valueStyle={{ color: simulationResults.statewide.winner === 'Republican' ? '#cf1322' : '#1890ff' }}
                  />
                </Card>
              </Col>
              <Col xs={24} sm={12} md={6}>
                <Card size="small">
                  <Statistic
                    title="Margin"
                    value={Math.abs(parseFloat(simulationResults.statewide.margin))}
                    suffix="%"
                    prefix={parseFloat(simulationResults.statewide.margin) > 0 ? 'R+' : 'D+'}
                  />
                </Card>
              </Col>
              <Col xs={24} sm={12} md={6}>
                <Card size="small">
                  <Statistic title="Confidence" value={simulationResults.statewide.confidence} />
                </Card>
              </Col>
              <Col xs={24} sm={12} md={6}>
                <Card size="small">
                  <Statistic
                    title="Projected Turnout"
                    value={simulationResults.statewide.totalVotes.toLocaleString()}
                    suffix={` (${simulationResults.statewide.turnoutRate}%)`}
                  />
                </Card>
              </Col>
            </Row>

            <Row gutter={[16, 16]} className={styles.voteRow}>
              <Col xs={24} sm={12}>
                <Card size="small">
                  <Statistic
                    title="Republican Votes"
                    value={simulationResults.statewide.repVotes.toLocaleString()}
                    suffix={`(${simulationResults.statewide.repPct}%)`}
                    valueStyle={{ color: '#cf1322' }}
                  />
                </Card>
              </Col>
              <Col xs={24} sm={12}>
                <Card size="small">
                  <Statistic
                    title="Democrat Votes"
                    value={simulationResults.statewide.demVotes.toLocaleString()}
                    suffix={`(${simulationResults.statewide.demPct}%)`}
                    valueStyle={{ color: '#1890ff' }}
                  />
                </Card>
              </Col>
            </Row>

            {simulationResults.districts.length > 0 && (
              <>
                <Title level={5} className={styles.sectionTitle}>District Breakdown</Title>
                <Table
                  columns={districtColumns}
                  dataSource={simulationResults.districts.map((d, i) => ({ ...d, key: i }))}
                  size="small"
                  pagination={false}
                  scroll={{ x: 900 }}
                />
              </>
            )}
          </div>
        ) : (
          <Empty description="Run a simulation to see results" className={styles.emptyState} />
        ),
      },
      {
        key: 'countyMap',
        label: 'County Map',
        children: (
          <div className={styles.mapContainer}>
            <SimulatorMap countyResults={countyResults} />
          </div>
        ),
      },
      {
        key: 'scenarios',
        label: `Scenarios (${scenarios.length})`,
        children: scenarios.length > 0 ? (
          <div className={styles.scenariosContent}>
            <Table
              dataSource={scenarios.map((s) => ({
                key: s.id,
                label: s.label,
                race: RACE_LABELS[s.results.parameters.race] || s.results.parameters.race,
                winner: s.results.statewide.winner,
                margin: s.results.statewide.margin,
                turnout: s.results.parameters.turnoutPercent,
                swing: s.results.parameters.partySwing,
                timestamp: s.timestamp,
              }))}
              columns={[
                { title: 'Scenario', dataIndex: 'label', key: 'label' },
                { title: 'Race', dataIndex: 'race', key: 'race' },
                { title: 'Winner', dataIndex: 'winner', key: 'winner',
                  render: (v) => <Tag color={v === 'Republican' ? 'red' : 'blue'}>{v}</Tag>,
                },
                { title: 'Margin', dataIndex: 'margin', key: 'margin',
                  render: (v) => {
                    const num = parseFloat(v)
                    return `${num > 0 ? 'R+' : 'D+'}${Math.abs(num).toFixed(1)}%`
                  },
                },
                { title: 'Turnout', dataIndex: 'turnout', key: 'turnout', render: (v) => `${v}%` },
                { title: 'Swing', dataIndex: 'swing', key: 'swing', render: (v) => `${v > 0 ? '+' : ''}${v}%` },
                { title: 'Saved', dataIndex: 'timestamp', key: 'timestamp' },
              ]}
              size="small"
              pagination={false}
            />
          </div>
        ) : (
          <Empty description="Save simulation results to compare scenarios" />
        ),
      },
    ]
    return items
  }, [simulationResults, scenarios, countyResults])

  return (
    <div className={styles.resultsPanel}>
      <Title level={5} className={styles.panelTitle}>
        {RACE_LABELS[selectedRace] || 'Election'} Simulation
      </Title>
      <Tabs items={tabItems} />
    </div>
  )
}

export default memo(SimulatorResults)
