import React from 'react'
import CountyDataImportModal from './CountyDataImportModal.jsx'
import useSimulatorData from './hooks/useSimulatorData.jsx'
import SimulatorResults from './SimulatorResults.jsx'
import SimulatorToolPanel from './SimulatorToolPanel.jsx'
import styles from './SimulatorContainer.module.css'

const SimulatorContainer = () => {
  const simulatorData = useSimulatorData()

  return (
    <div className={styles.container}>
      <SimulatorToolPanel {...simulatorData} />
      <SimulatorResults
        simulationResults={simulatorData.simulationResults}
        scenarios={simulatorData.scenarios}
        currentRaceData={simulatorData.currentRaceData}
        selectedRace={simulatorData.selectedRace}
        countyResults={simulatorData.countyResults}
      />
      <CountyDataImportModal
        open={simulatorData.showImportModal}
        onClose={() => simulatorData.setShowImportModal(false)}
        onSave={simulatorData.saveRaceData}
      />
    </div>
  )
}

export default SimulatorContainer
