// Helper to get classification for a given FIPS code
export function getCountyClassification(fips) {
  if (COUNTY_CLASSIFICATIONS.urban.includes(fips)) return 'urban'
  if (COUNTY_CLASSIFICATIONS.suburban.includes(fips)) return 'suburban'
  return 'rural'
}

// Helper to look up which metro area a county belongs to (if any)
export function getMetroArea(fips) {
  for (const [key, metro] of Object.entries(METRO_AREAS)) {
    if (metro.counties.includes(fips)) return { key, ...metro }
  }
  return null
}
