import { useCallback, useMemo, useState } from 'react'
import { congressionalData, historicalData, RACE_TYPES } from '../data/missouriElectionData.js'
import useCountyElectionData from './useCountyElectionData.jsx'

const MAX_SCENARIOS = 3

const useSimulatorData = () => {
  const [selectedRace, setSelectedRace] = useState(RACE_TYPES.PRESIDENTIAL_2020)
  const [turnoutPercent, setTurnoutPercent] = useState(75)
  const [partySwing, setPartySwing] = useState(0)
  const [urbanModifier, setUrbanModifier] = useState(0)
  const [suburbanModifier, setSuburbanModifier] = useState(0)
  const [ruralModifier, setRuralModifier] = useState(0)
  const [simulationResults, setSimulationResults] = useState(null)
  const [countyResults, setCountyResults] = useState(null)
  const [scenarios, setScenarios] = useState([])
  const [showImportModal, setShowImportModal] = useState(false)

  const {
    loading: countyDataLoading, error: countyDataError,
    saveRaceData, getCountyDataForRace, availableRaces,
  } = useCountyElectionData()

  const currentRaceData = useMemo(() => {
    if (historicalData[selectedRace]) {
      return historicalData[selectedRace]
    }
    if (congressionalData[selectedRace]) {
      return { statewide: congressionalData[selectedRace], districts: [] }
    }
    return null
  }, [selectedRace])

  const runSimulation = useCallback(() => {
    if (!currentRaceData) return null

    const baselineData = currentRaceData
    const turnoutMultiplier = turnoutPercent / 100
    const swingFactor = partySwing / 100

    const modifiers = { urban: urbanModifier / 100, suburban: suburbanModifier / 100, rural: ruralModifier / 100 }

    const baseRepPct = baselineData.statewide.repPct / 100
    const baseDemPct = baselineData.statewide.demPct / 100
    const baseTotalVotes = baselineData.statewide.totalVotes

    const projectedTotalVotes = Math.round(baseTotalVotes * turnoutMultiplier)
    const adjustedRepPct = Math.min(1, Math.max(0, baseRepPct + swingFactor))
    const adjustedDemPct = Math.min(1, Math.max(0, baseDemPct - swingFactor))
    const projectedRepVotes = Math.round(projectedTotalVotes * adjustedRepPct)
    const projectedDemVotes = Math.round(projectedTotalVotes * adjustedDemPct)
    const margin = ((adjustedRepPct - adjustedDemPct) * 100).toFixed(1)
    const winner = adjustedRepPct > adjustedDemPct ? 'Republican' : 'Democrat'

    const absMargin = Math.abs(parseFloat(margin))
    let confidence = 'Toss-up'
    if (absMargin > 15) confidence = 'Safe'
    else if (absMargin > 10) confidence = 'Likely'
    else if (absMargin > 5) confidence = 'Lean'
    else if (absMargin > 2) confidence = 'Slight Lean'

    const districtResults = (baselineData.districts || []).map((district) => {
      const classModifier = modifiers[district.classification] || 0
      const distRepPct = district.repPct / 100
      const distDemPct = district.demPct / 100
      const distTotalVotes = Math.round(district.totalVotes * turnoutMultiplier)

      const adjRepPct = Math.min(1, Math.max(0, distRepPct + swingFactor + classModifier))
      const adjDemPct = Math.min(1, Math.max(0, distDemPct - swingFactor - classModifier))

      const distRepVotes = Math.round(distTotalVotes * adjRepPct)
      const distDemVotes = Math.round(distTotalVotes * adjDemPct)
      const distMargin = ((adjRepPct - adjDemPct) * 100).toFixed(1)
      const baselineMargin = ((distRepPct - distDemPct) * 100).toFixed(1)
      const swingFromBaseline = (parseFloat(distMargin) - parseFloat(baselineMargin)).toFixed(1)

      return {
        name: district.name,
        classification: district.classification,
        repVotes: distRepVotes,
        demVotes: distDemVotes,
        totalVotes: distTotalVotes,
        repPct: (adjRepPct * 100).toFixed(1),
        demPct: (adjDemPct * 100).toFixed(1),
        margin: distMargin,
        baselineMargin,
        swingFromBaseline,
      }
    })

    const results = {
      statewide: {
        winner, margin, confidence,
        repVotes: projectedRepVotes, demVotes: projectedDemVotes,
        totalVotes: projectedTotalVotes,
        repPct: (adjustedRepPct * 100).toFixed(1),
        demPct: (adjustedDemPct * 100).toFixed(1),
        turnoutRate: turnoutPercent,
      },
      districts: districtResults,
      parameters: { race: selectedRace, turnoutPercent, partySwing, urbanModifier, suburbanModifier, ruralModifier },
    }

    setSimulationResults(results)

    // County-level simulation
    const countyRaceData = getCountyDataForRace(selectedRace)
    if (countyRaceData && countyRaceData.counties) {
      const countySimResults = countyRaceData.counties.map((county) => {
        const classModifier = modifiers[county.classification] || 0
        const cRepPct = county.repPct / 100
        const cDemPct = county.demPct / 100
        const cTotalVotes = Math.round(county.totalVotes * turnoutMultiplier)

        const adjRepPct = Math.min(1, Math.max(0, cRepPct + swingFactor + classModifier))
        const adjDemPct = Math.min(1, Math.max(0, cDemPct - swingFactor - classModifier))

        const cRepVotes = Math.round(cTotalVotes * adjRepPct)
        const cDemVotes = Math.round(cTotalVotes * adjDemPct)
        const cMargin = ((adjRepPct - adjDemPct) * 100).toFixed(1)

        return {
          countyfips: county.countyfips,
          countyname: county.countyname,
          classification: county.classification,
          repVotes: cRepVotes,
          demVotes: cDemVotes,
          totalVotes: cTotalVotes,
          repPct: (adjRepPct * 100).toFixed(1),
          demPct: (adjDemPct * 100).toFixed(1),
          margin: cMargin,
        }
      })
      setCountyResults(countySimResults)
    } else {
      setCountyResults(null)
    }

    return results
  }, [currentRaceData, turnoutPercent, partySwing, urbanModifier, suburbanModifier, ruralModifier, selectedRace, getCountyDataForRace])

  const saveScenario = useCallback(() => {
    if (!simulationResults) return
    setScenarios((prev) => {
      const next = [...prev]
      if (next.length >= MAX_SCENARIOS) next.shift()
      next.push({ id: Date.now(), label: `Scenario ${prev.length + 1}`, results: simulationResults, timestamp: new Date().toLocaleString() })
      return next
    })
  }, [simulationResults])

  const clearScenarios = useCallback(() => setScenarios([]), [])

  const resetParameters = useCallback(() => {
    setTurnoutPercent(75)
    setPartySwing(0)
    setUrbanModifier(0)
    setSuburbanModifier(0)
    setRuralModifier(0)
    setSimulationResults(null)
    setCountyResults(null)
  }, [])

  return {
    selectedRace, setSelectedRace,
    turnoutPercent, setTurnoutPercent,
    partySwing, setPartySwing,
    urbanModifier, setUrbanModifier,
    suburbanModifier, setSuburbanModifier,
    ruralModifier, setRuralModifier,
    simulationResults, scenarios, currentRaceData,
    countyResults, countyDataLoading, countyDataError,
    showImportModal, setShowImportModal,
    saveRaceData, availableRaces,
    runSimulation, saveScenario, clearScenarios, resetParameters,
  }
}

export default useSimulatorData
